static void expressions_clear(struct neocc_expressions *state)
{
	memset(state, 0, sizeof(*state));
	state->top = state->values;
}

static int expressions_open(struct object *self,
	const struct vr *caller_context)
{
	struct em_expressions *members = self->members;

	OBS_OBJECT_OPEN_;
	if (self->ref_count != 1)
		return R_P;
	members->state = calloc(1, sizeof(*members->state));
	if (!members->state)
		return R_N; /* The opened base must still be closed by the caller. */
	expressions_clear(members->state);
	return R_P;
}

static int expressions_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_expressions *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (self->ref_count || !members->state)
		return R_P;
	expressions_clear(members->state);
	free(members->state);
	members->state = NULL;
	return R_P;
}

static int expressions_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_expressions *members = self->members;

	if (action != NEOCC_AC0_EXPRESSIONS_RESET) {
		SBO_OBJECT_INTERACT0;
	}

	if (!self->ref_count || !members->state)
		return RN_INVALIDARG;
	expressions_clear(members->state);
	return R_P;
}

