static int expressions_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_expressions *members = self->members;
	struct neocc_expressions *state = members->state;

	*output_quantity = 0;
	if (action != NEOCC_AC1_EXPRESSIONS_BORROW) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || !state)
		return RN_INVALIDARG;
	if (capacity < sizeof(state))
		return RN_INVALIDARG;
	memcpy(output_stream, &state, sizeof(state));
	*output_quantity = sizeof(state);
	return R_P;
}

